def transform(grid):
    H, W = len(grid), len(grid[0])
    # Determine background color (most frequent)
    counts = {}
    for r in range(H):
        for c in range(W):
            v = grid[r][c]
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get) if counts else 0

    # Identify Main Block: Largest rectangular connected component of non-bg color
    visited = set()
    best_r_min, best_r_max, best_c_min, best_c_max = -1, -1, -1, -1
    best_area = 0

    for r in range(H):
        for c in range(W):
            if grid[r][c] == bg or (r, c) in visited: 
                continue

            # BFS to identify component
            color = grid[r][c]
            comp = []
            stack = [(r, c)]
            visited.add((r, c))

            while stack:
                cr, cc = stack.pop()
                comp.append((cr, cc))
                for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    nr, nc = cr + dr, cc + dc
                    if 0 <= nr < H and 0 <= nc < W and (nr, nc) not in visited and grid[nr][nc] == color:
                        visited.add((nr, nc))
                        stack.append((nr, nc))

            # If component is solid rectangle, check size
            if not comp:
                continue

            r_min, r_max = min(p[0] for p in comp), max(p[0] for p in comp)
            c_min, c_max = min(p[1] for p in comp), max(p[1] for p in comp)

            is_rect = True
            for i in range(r_min, r_max + 1):
                for j in range(c_min, c_max + 1):
                    if grid[i][j] != color:
                        is_rect = False
                        break
                if not is_rect:
                    break

            if is_rect:
                area = (r_max - r_min + 1) * (c_max - c_min + 1)
                if area > best_area:
                    best_area = area
                    best_r_min, best_r_max = r_min, r_max
                    best_c_min, best_c_max = c_min, c_max

    # If no main block found, return grid
    if best_area == 0:
        return grid

    # Create output grid as a copy
    out = [row[:] for row in grid]
    tl, tr, cl, cr = best_r_min, best_r_max, best_c_min, best_c_max

    # Project Source Pixels to Main Block boundaries
    for r in range(H):
        for c in range(W):
            if grid[r][c] == bg:
                continue

            # If pixel is above Main Block (Top Source)
            if r < tl and cl <= c <= cr:
                out[tl][c] = grid[r][c]
            # If pixel is below Main Block (Bottom Source)
            elif r > tr and cl <= c <= cr:
                out[tr][c] = grid[r][c]
            # If pixel is to the left of Main Block (Left Source)
            elif c < cl and tl <= r <= tr:
                out[r][cl] = grid[r][c]
            # If pixel is to the right of Main Block (Right Source)
            elif c > cr and tl <= r <= tr:
                out[r][cr] = grid[r][c]

    return out
